  el.classList.toggle('active',force>200);el.classList.toggle('failed',p.allThrustersOff||p.failedNozzle===i);el.dataset.failed=String(p.allThrustersOff||p.failedNozzle===i);el.setAttribute('aria-valuemax',String(rating));el.setAttribute('aria-valuenow',force.toFixed(1));el.setAttribute('aria-valuetext',fmt(force/1000,2)+' kN');
  el.setAttribute('aria-label',NOZZLES[i].name+': '+fmt(force/1000,2)+' kN');el.title=NOZZLES[i].name+' · '+fmt(force/1000,2)+' kN';
