function label(ctx,text,x,y,color='#819880',size=9,align='left'){ctx.fillStyle=['#819880','#71896c','#7f9378','#869d7b','#8a9e7f','#819877','#8da080','#79966c'].includes(color)?'#b0bfa9':color;ctx.font=Math.max(13,size)+'px "IBM Plex Mono",monospace';ctx.textAlign=align;ctx.fillText(text,x,y);}
function line(ctx,x1,y1,x2,y2,color,width=1,dash=[]){ctx.beginPath();ctx.setLineDash(dash);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.setLineDash([]);}
