const replayOptions={camera:'follow',yaw:0,elevation:0,zoom:1,vectors:true,trails:true};
function drawScene(){
 if(!result)return;const {ctx,w,h}=canvasContext(scene);if(!w||!h)return;
 renderReplay(ctx,w,h,{result,unpowered,sample:displaySampleAt(time),time,options:replayOptions});
}

function drawPlot(){if(!result)return;if(chart==='attitude'){drawAttitudePlot();return;}const {ctx,w,h}=canvasContext(plot);if(!w)return;ctx.clearRect(0,0,w,h);const left=62,right=32,top=30,bottom=h-42,ww=w-left-right,hh=bottom-top;const end=Math.max(.001,result.final.t);const get=s=>chart==='height'?Math.max(0,s.clearance):chart==='thrust'?s.thrust/1000:chart==='attitude'?degrees(s.tilt):s.gas;const unit=chart==='height'?'m':chart==='thrust'?'Σ kN':chart==='attitude'?'° tilt':'kg';const rawmax=Math.max(1,...result.samples.map(get));const max=Math.ceil(rawmax/(rawmax>100?50:rawmax>30?10:5))*(rawmax>100?50:rawmax>30?10:5);const X=t=>left+t/end*ww,Y=v=>bottom-v/max*hh;for(let k=0;k<=3;k++){const v=max*k/3;line(ctx,left,Y(v),w-right,Y(v),'#2b352b',.7);label(ctx,fmt(v,0),left-9,Y(v)+3,'#7f9378',7,'right');}for(let k=0;k<=4;k++){const t=end*k/4;label(ctx,fmt(t,1)+'s',X(t),h-10,'#7f9378',7,'center');}label(ctx,unit,16,19,'#869d7b',7);
const grad=ctx.createLinearGradient(0,top,0,bottom);grad.addColorStop(0,'rgba(216,247,155,.09)');grad.addColorStop(1,'rgba(216,247,155,0)');ctx.beginPath();ctx.moveTo(X(0),bottom);result.samples.forEach(s=>ctx.lineTo(X(s.t),Y(get(s))));ctx.lineTo(X(end),bottom);ctx.closePath();ctx.fillStyle=grad;ctx.fill();ctx.beginPath();result.samples.forEach((s,i)=>i?ctx.lineTo(X(s.t),Y(get(s))):ctx.moveTo(X(s.t),Y(get(s))));ctx.strokeStyle='#b9da8b';ctx.lineWidth=1.4;ctx.stroke();if(result.airborneStart!==null&&result.airborneStart>0){line(ctx,X(result.airborneStart),top,X(result.airborneStart),bottom,'#c6c596',1,[3,3]);label(ctx,'RELEASE',Math.min(X(result.airborneStart)+4,w-right-65),top+36,'#c6c596',7);}if(result.burnStart!==null){line(ctx,X(result.burnStart),top,X(result.burnStart),bottom,'#618c80',.7,[3,4]);label(ctx,'BURN',Math.min(X(result.burnStart)+5,w-right-40),top+15,'#85b5a3',6.5);}const current=sampleAt(time);line(ctx,X(time),top,X(time),bottom,'rgba(229,244,209,.7)',.8);ctx.beginPath();ctx.arc(X(time),Y(get(current)),3,0,Math.PI*2);ctx.fillStyle='#d8f79b';ctx.fill();}
function computeMap(){mapDirty=false;$('#map-status').textContent='Running 121 ramp/flight cases…';if(mapWorker)mapWorker.terminate();const id=++mapJob;try{mapWorker=new Worker('map-worker.js?v=4.4',{type:'module'});}catch(error){mapData={error:true};$('#map-status').textContent='Map worker unavailable; individual replay remains available.';return;}mapWorker.onmessage=e=>{if(e.data.id!==mapJob)return;if(e.data.progress){$('#map-status').textContent='Computed '+e.data.progress+' / 121 cases…';return;}mapData=e.data;$('#map-status').textContent=(params.feedModel==='optimistic'?'Under the optimistic independent feed bound: ':'Using the consistent feed solve: ')+mapData.stats.landing+' / '+mapData.stats.tested+' tested cases pass landing limits; '+mapData.stats.hardware+' pass hardware; '+mapData.stats.both+' pass both. '+mapData.stats.excluded+' cells below the component mass floor were not simulated.';mapWorker.terminate();mapWorker=null;drawMap();};mapWorker.onerror=()=>{if(id!==mapJob)return;mapData={error:true};$('#map-status').textContent='Map worker unavailable; use the individual replay.';mapWorker?.terminate();mapWorker=null;drawMap();};mapWorker.postMessage({id,params});}
function drawMap(){if(view!=='map')return;if(mapDirty)computeMap();const {ctx,w,h}=canvasContext(map);if(!w)return;ctx.clearRect(0,0,w,h);if(!mapData){label(ctx,'Calculating scenarios…',w/2,h/2,'#b9d696',8,'center');return;}if(mapData.error){label(ctx,'Map unavailable; replay still works.',w/2,h/2,'#edb394',8,'center');return;}const {masses,forces,cells}=mapData,l=61,r=25,t=25,b=h-48,cw=(w-l-r)/masses.length,ch=(b-t)/forces.length;for(let j=0;j<forces.length;j++)for(let i=0;i<masses.length;i++){ctx.fillStyle=cells[j][i]===null?'#424b47':(['#673f35','#79b8c8','#d6ad60','#a2c574'][cells[j][i]]);ctx.fillRect(l+i*cw+.7,b-(j+1)*ch+.7,cw-1.4,ch-1.4);}for(let i=0;i<masses.length;i+=2)label(ctx,(masses[i]/1000).toFixed(2)+'t',l+(i+.5)*cw,b+17,'#9aac91',8,'center');for(let j=0;j<forces.length;j+=2)label(ctx,forces[j]+'',l-10,b-(j+.5)*ch+3,'#9aac91',8,'right');label(ctx,'MAX THRUST / kN',l,t-10,'#8a9e7f',7);label(ctx,'REQUESTED WET MASS',w/2,h-7,'#8a9e7f',7,'center');const xx=l+(params.mass-875)/250*cw,yy=b-(params.thrust-15)/10*ch;if(xx>=l&&xx<=w-r&&yy>=t&&yy<=b){ctx.beginPath();ctx.arc(xx,yy,5,0,Math.PI*2);ctx.fillStyle='#f4f6e8';ctx.fill();ctx.strokeStyle='#111911';ctx.lineWidth=2;ctx.stroke();}}
function drawAll(){if(view==='replay')drawScene();else drawMap();drawPlot();}
function tick(now){
 frameRequest=null;
 if(!playing)return;
 time=Math.min(result.final.t,time+Math.min((now-lastTick)/1000,.08)*Number($('#play-rate').value));
 if(time>=result.final.t)playing=false;lastTick=now;updatePlayback();drawAll();
 if(playing)frameRequest=requestAnimationFrame(tick);
}
function start(){
 if(time>=result.final.t-.003)time=0;playing=true;lastTick=performance.now();updatePlayback();
 if(!frameRequest)frameRequest=requestAnimationFrame(tick);
}

