document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing){playing=false;updatePlayback();}});
const resize=new ResizeObserver(()=>{drawAll();drawHardware();if(result)drawAttitudeGauge(sampleAt(time));});resize.observe($('.experiment'));resize.observe(scene);resize.observe(plot);window.addEventListener('resize',()=>{drawAll();drawHardware();});document.fonts?.ready.then(()=>{drawAll();drawHardware();});syncControls();recalculate();

function drawHardware(){if(!result)return;const hw=result.hardware,fan=hw.fan,p=result.p,gas=tankState(p,p.gas),supply=nozzleSupply(p,gas),minT=result.minimumTemperature-273.15,minFeed=result.minimumFeedTemperature-273.15;$('#hw-fan').innerHTML=fmt(fan.wanted.inletQ,2)+' <small>m³/s</small> / '+fmt(fan.wanted.power/1000,0)+' <small>kW</small>';$('#hw-fan-note').textContent=fmt(params.fanGap,1)+' mm gap · '+fmt(fan.wanted.delta/1000,1)+' kPa for '+fmt(params.suction,1)+'× weight. '+(fan.canReachTarget?'Within the assumed fan limits.':'Exceeds an assumed fan limit.');$('#hw-storage').innerHTML=fmt(gas.initialPressure/1e5,0)+' <small>bar</small> / '+fmt(hw.tankMass,0)+' <small>kg</small>';$('#hw-storage-note').textContent=fmt(params.gas,0)+' kg of gas in '+fmt(params.tankVolume,0)+' L. '+(params.realGas?(params.gasModel==='pr'?'Peng–Robinson comparison; known dense-gas bias.':'CoolProp reference nitrogen tables; see interpolation validation below.'):'Ideal air comparison.');$('#hw-mass').innerHTML=fmt(hw.minimumWetMass,0)+' <small>kg</small>';$('#hw-mass-note').textContent='Battery '+fmt(hw.batteryMass,0)+' + structure '+fmt(hw.structure,0)+' + vessels '+fmt(hw.tankMass,0)+' + fans '+fmt(hw.fanMass,0)+' + valves/mounts '+fmt(hw.ancillaries,0)+' + gas '+fmt(params.gas,0)+' kg.';$('#hw-cold').innerHTML=result.eosInvalidState?'Unavailable':fmt(minT,0)+' <small>°C</small>';$('#hw-cold-note').textContent=result.eosInvalidState?'No validated temperature minimum: the gas state left the EOS domain.':(result.hasGasFlow?'Flowing regulator minimum: '+fmt(minFeed,0)+' °C; ':'Regulator inactive: no gas discharge. ')+'Selected limit '+fmt(params.minimumGasTemperature,0)+' °C. '+(result.thermalFits?'Within that assumed limit.':'Below that assumed limit.');$('#hardware-status').textContent=(result.candidate?'All selected model checks pass. ':result.reason+' ')+'Actual vehicle fit remains unverified; the drawing uses assumed internal bays and custom tank geometry.';$('#fit-label').textContent=hw.packageFits?'FITS ASSUMED BAYS':'SPACE CONFLICT';$('#fit-label').style.color=hw.packageFits?'var(--lime)':'var(--bad)';$('#tank-sizes').innerHTML='Passenger-space tank: '+fmt(hw.large.volume*1000,0)+' L → '+fmt(hw.large.outerLength,2)+' m × Ø'+fmt(hw.large.outerDiameter,2)+' m<br>Rear tank: '+fmt(hw.small.volume*1000,0)+' L → '+fmt(hw.small.outerLength,2)+' m × Ø'+fmt(hw.small.outerDiameter,2)+' m<br>Battery: '+fmt(hw.batteryVolume*1000,0)+' L within an assumed 552 L floor bay; one driver seat.';const boundary=gasInventoryAtRegulator(p);const rows=[['Selected feed model',p.feedModel==='optimistic'?'Optimistic independent bound':'Consistent pressure/flow solve'],['Lowest flowing nozzle-inlet pressure',fmt(Number.isFinite(result.minimumManifoldPressure)?result.minimumManifoldPressure/1e5:null,1)+' bar'],['Feed-limited duration',fmt(result.feedBindingTime,3)+' s'],['Maximum demand above same-pressure feed capacity',fmt(result.maximumFeedDeficit,4)+' kg/s'],['Regulator target / delivery loss',fmt(p.regulatorBar,0)+' bar / '+fmt(p.deliveryLossPercent,0)+'%'],['Initial nozzle-pressure ceiling',fmt(gas.feedPressure/1e5,1)+' bar'],['Gas above regulator pressure boundary',fmt(boundary.gasAboveSetpoint,1)+' kg (not guaranteed rated-thrust inventory)'],...(result.ramp?[['Actual ramp peak electrical power',fmt(result.ramp.peakPowerW/1000,1)+' kW'],['Ramp minimum contact normal force',fmt(result.ramp.minimumNormal/1000,1)+' kN'],['Ramp battery energy',fmt(result.ramp.batteryEnergyJ/3.6e6,3)+' kWh']]:[]),['Seal geometry bounds',hw.sealGeometryFits?'Within necessary floor/perimeter bounds':'Impossible selected seal geometry'],['Control command delay',fmt(params.controlDelay,0)+' ms'],['Required seal travel',fmt(hw.requiredSkirtTravel*1000,0)+' / '+fmt(params.skirtTravel,0)+' mm available'],...(!result.ramp?[['Steady-speed ramp grip / demand',fmt(hw.gripMargin,2)+'×'],['Steady-speed ramp power / budget',fmt((hw.peakRampElectricalPower??0)/1000,0)+' / '+fmt(params.batteryPower,0)+' kW'],['Gravity-climb wheel power',fmt(hw.rampGravityPower/1000,0)+' kW at exit speed']]:[]),['Achievable surface suction',fmt(fan.maxSuction/(p.mass*G),2)+'× weight (limit)'],['Four-jet nozzle-only force ceiling',fmt(4*supply.downCap/1000,1)+' kN ceiling'],[p.feedModel==='optimistic'?'Initial optimistic feed-capacity bound':'Initial feed capacity at pressure ceiling',fmt(p.feedModel==='optimistic'?supply.feedMdot:feedCapacityAtPressure(p,gas,gas.feedPressure),0)+' kg/s'],['Peak flight gas discharge',fmt(result.maxFlow,0)+' kg/s'],['Feed equivalent / each lift throat',fmt(params.feedDiameter,0)+' / '+fmt(params.throat,0)+' mm'],['First-point downward speed',fmt(result.contactVerticalSpeed,2)+' m/s'],['Peak seat specific load (modeled phases)',fmt(result.peakSeatLoad,2)+' g'],['Isothermal heat demand / available',fmt((result.maxHeatPower??0)/1000,0)+' / '+fmt(params.heatTransferPower,0)+' kW'],['Heat required for isothermal assumption',fmt((result.heatRequired??0)/1e6,2)+' MJ'],['Assumed cold operating limit',fmt(params.minimumGasTemperature,0)+' °C'],['Commanded surface suction',fmt(fan.actualSuction/(p.mass*G),2)+'× weight'],['Valve time constant',fmt(params.valveLag,0)+' ms'],['Wet mass actually simulated',fmt(p.mass,0)+' kg'],['Signed longitudinal contact speed',result.landed?fmt(result.longitudinalSpeed,2)+' m/s · '+(result.longitudinalSpeed<0?'backward':'forward'):'No contact'],['Longitudinal magnitude limit',fmt(p.longitudinalSpeedLimit,1)+' m/s'],['Controller rotation / heading',p.flipMode+' / '+p.headingMode]];$('#supply-table').innerHTML=rows.map(([a,b])=>'<div class="supply-row"><span>'+a+'</span><strong>'+b+'</strong></div>').join('');$('#thermal-note').textContent='Tank blowdown and regulator throttling are separate cooling processes. '+(params.realGas?(params.gasModel==='pr'?'Peng–Robinson nitrogen uses ':'Reference nitrogen tables use ')+(params.blowdown?'adiabatic tank blowdown':'a tank held isothermal with the displayed heat requirement')+' and constant enthalpy through the regulator. ':'Ideal air has zero Joule–Thomson change. '+(params.blowdown?'':'Isothermal operation needs the displayed heat input. '))+(result.eosInvalidState?'The gas state left the validated EOS domain; thrust stopped and the run cannot pass. ':result.phaseLimited?'A saturation/liquid or unresolved phase cell was reached; thrust is conservatively stopped. ':'No flagged phase cell was encountered. This does not resolve nozzle condensation.')+' Regulator temperature and effective exhaust speed remain evaluated at the pre-solve pressure ceiling, even when the hydraulic solve lowers nozzle pressure. This is not a fully coupled thermodynamic manifold model. Perfectly expanded nozzle flow may be colder still; actual exit temperature needs nozzle and phase calculations.';drawPackaging();drawThermal();}
function drawPackaging(){const {ctx,w,h}=canvasContext($('#packaging'));if(!w)return;ctx.clearRect(0,0,w,h);const hw=result.hardware,scale=Math.min((w-45)/4.8,(h-100)/2.5),X=x=>w/2+x*scale,Y=y=>h*.43-y*scale;const rect=(x,y,l,d,fill,stroke)=>{ctx.fillStyle=fill;ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.fillRect(X(x),Y(y+d),l*scale,d*scale);ctx.strokeRect(X(x),Y(y+d),l*scale,d*scale);};const tank=(cx,cy,t,fill)=>{const len=t.outerLength*scale,diam=t.outerDiameter*scale;ctx.beginPath();ctx.roundRect(X(cx)-len/2,Y(cy)-diam/2,len,diam,diam/2);ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle='#d2ecaf';ctx.lineWidth=1;ctx.stroke();};ctx.beginPath();const outline=[[-2.3,-.85],[-1.8,-.97],[1.45,-.97],[2.3,-.65],[2.3,.65],[1.45,.97],[-1.8,.97],[-2.3,.85]];outline.forEach(([x,y],i)=>i?ctx.lineTo(X(x),Y(y)):ctx.moveTo(X(x),Y(y)));ctx.closePath();ctx.fillStyle='#233024';ctx.fill();ctx.strokeStyle='#728665';ctx.lineWidth=1;ctx.stroke();rect(-1.15,-.75,2.3,1.5,'rgba(104,138,144,.16)','#435e59');rect(-.5,-.9,1.75,.82,'rgba(172,203,117,.06)','#5b7144');rect(-2,-.55,1.45,1.1,'rgba(172,203,117,.06)','#5b7144');rect(-.5,.08,1.75,.82,'#273c3a','#547a72');label(ctx,'DRIVER',X(.3),Y(.46),'#9fcec1',8,'center');tank(.375,-.49,hw.large,'#52663c');tank(-1.275,0,hw.small,'#52663c');label(ctx,fmt(hw.large.volume*1000,0)+' L',X(.375),Y(-.49)+3,'#e3f0d1',8,'center');label(ctx,fmt(hw.small.volume*1000,0)+' L',X(-1.275),Y(0)+3,'#e3f0d1',8,'center');for(const x of [-1.5,1.5])for(const y of [-1.0,1.0])rect(x-.3,y-.12,.6,.24,'#111b13','#506445');for(let i=0;i<4;i++){const y=-.54+i*.36;ctx.beginPath();ctx.arc(X(-2.15),Y(y),params.fanDiameter/2*scale,0,Math.PI*2);ctx.fillStyle='#244c45';ctx.fill();ctx.strokeStyle='#82b9a6';ctx.stroke();}for(const [x,y] of [[-1.55,-.72],[-1.55,.72],[1.55,-.72],[1.55,.72]]){line(ctx,X(-.5),Y(-.49),X(x),Y(y),'#69acb0',1,[3,3]);ctx.fillStyle='#a4dfe0';ctx.beginPath();ctx.arc(X(x),Y(y),3,0,Math.PI*2);ctx.fill();}label(ctx,'FRONT →',X(1.6),Y(1.25),'#8da080',7,'center');const below=Y(-1.0)+38;line(ctx,X(-2.3),below,X(2.3),below,'#617852',.7);label(ctx,'4.60 m assumed exterior',w/2,below+15,'#a8bd98',8,'center');const sideY=h-22;ctx.fillStyle='#35504a';ctx.fillRect(X(-1.15),sideY-8,2.3*scale,.16*scale);ctx.fillStyle='#698449';ctx.fillRect(X(-.5),sideY-.8*scale,Math.min(hw.large.outerLength,2.5)*scale,hw.large.outerDiameter*scale);label(ctx,'Battery below · tank above',w/2,h-10,'#a6baa0',13,'center');}
function drawThermal(){const {ctx,w,h}=canvasContext($('#thermal'));if(!w)return;ctx.clearRect(0,0,w,h);if(result.eosInvalidState){label(ctx,'Temperature path unavailable: EOS domain exceeded',w/2,h/2,'#edaa88',14,'center');return;}const l=54,r=w-16,t=28,b=h-34,min=Math.floor((Math.min(result.minimumTemperature,result.minimumFeedTemperature,params.minimumGasTemperature+273.15)-273.15-10)/25)*25,max=Math.max(25,params.ambientTemperature+5),X=x=>l+x/Math.max(.001,result.final.t)*(r-l),Y=y=>b-(y-min)/(max-min)*(b-t);for(let v=0;v>=min;v-=50){line(ctx,l,Y(v),r,Y(v),v===0?'#536254':'#29392a',.7,v===0?[3,3]:[]);label(ctx,v+'°',l-6,Y(v)+3,'#819877',7,'right');}line(ctx,l,Y(params.minimumGasTemperature),r,Y(params.minimumGasTemperature),'#edaa88',1,[4,3]);label(ctx,'assumed cold limit',r,Y(params.minimumGasTemperature)-4,'#edaa88',7,'right');for(const [key,color] of [['temperature','#c6e39a'],['feedTemperature','#86d4e4']]){ctx.beginPath();result.samples.forEach((s,i)=>{if(key==='feedTemperature'&&s.thrust<=0)return;const z=tankState(result.p,s.gas)[key]-273.15;i?ctx.lineTo(X(s.t),Y(z)):ctx.moveTo(X(s.t),Y(z));});ctx.strokeStyle=color;ctx.lineWidth=1.4;ctx.stroke();}label(ctx,'0 s',l,h-7,'#819877',7);label(ctx,fmt(result.final.t,2)+' s',r,h-7,'#819877',7,'right');}

function drawAttitudePlot(){const {ctx,w,h}=canvasContext(plot);if(!w)return;ctx.clearRect(0,0,w,h);const l=66,r=w-28,t=28,b=h-40,X=v=>l+v/Math.max(.001,result.final.t)*(r-l),Y=v=>b-(v+180)/360*(b-t);for(const v of [-180,0,180]){line(ctx,l,Y(v),r,Y(v),'#2b352b',.7);label(ctx,v+'°',l-7,Y(v)+3,'#7f9378',7,'right');}for(const [key,color,offset] of [['roll','#b9da8b',0],['pitch','#86d4e4',80],['yaw','#d9ad8b',168]]){ctx.beginPath();result.samples.forEach((s,i)=>i&&Math.abs(s[key]-result.samples[i-1][key])<Math.PI?ctx.lineTo(X(s.t),Y(degrees(s[key]))):ctx.moveTo(X(s.t),Y(degrees(s[key]))));ctx.strokeStyle=color;ctx.lineWidth=1.2;ctx.stroke();label(ctx,key.toUpperCase(),l+offset,t-4,color,7);}line(ctx,X(time),t,X(time),b,'#b4c4a5',.8);label(ctx,'0 s',l,h-10,'#7f9378',7);label(ctx,fmt(result.final.t,2)+' s',r,h-10,'#7f9378',7,'right');}

$('#run-audit').addEventListener('click',()=>{auditWorker?.terminate();const id=++auditJob;$('#run-audit').disabled=true;$('#audit-status').textContent='Running independent perturbations…';try{auditWorker=new Worker('map-worker.js?v=4.4',{type:'module'});}catch(error){$('#audit-status').textContent='Audit worker unavailable; individual replay remains available.';$('#run-audit').disabled=false;return;}auditWorker.onmessage=e=>{if(e.data.id!==auditJob)return;if(e.data.progress){$('#audit-status').textContent='Computed '+e.data.progress+' / '+e.data.total+' audit cases…';return;}auditData=e.data.rows;const passes=auditData.filter(x=>x.candidate).length;$('#audit-status').textContent=passes+' / '+auditData.length+' cases pass selected checks under their labelled feed model. Optimistic passes depend on an independent bound that may be unattainable. These are scenario tests, not a probability of success.';$('#audit-results').innerHTML='<table><thead><tr><th>Changed assumption</th><th>Feed model</th><th>Contact ↓</th><th>Forward / backward</th><th>Gas used</th><th>Ramp kWh / peak kW</th><th>Result</th></tr></thead><tbody>'+auditData.map(x=>'<tr><td>'+x.label+'</td><td>'+(x.feedModel==='optimistic'?'Optimistic bound':'Consistent solve')+'</td><td>'+fmt(x.contactVerticalSpeed,2)+' m/s</td><td>'+fmt(x.longitudinalSpeed,2)+' m/s</td><td>'+fmt(x.gasUsed,1)+' kg</td><td>'+fmt(x.rampEnergyKWh,3)+' / '+fmt(x.rampPeakPowerKW,1)+'</td><td class="'+(x.candidate?'audit-pass':'audit-fail')+'">'+(x.candidate?(x.feedModel==='optimistic'?'Passes under optimistic bound':'Passes selected checks'):x.reason)+'</td></tr>').join('')+'</tbody></table>';auditWorker.terminate();auditWorker=null;$('#run-audit').disabled=false;};auditWorker.onerror=()=>{if(id!==auditJob)return;$('#audit-status').textContent='Audit worker unavailable; individual replay remains available.';$('#run-audit').disabled=false;auditWorker?.terminate();auditWorker=null;};auditWorker.postMessage({id,kind:'audit',params});});
